export const modelTopics = [
 {code:'L11301',title:'機器學習基本原理',moduleId:'machine-learning',lessonIds:['ml-learning'],summary:'判斷學習方式時，先看模型取得什麼回饋：監督式利用已知標籤學習輸入與目標的關係；非監督式從沒有指定答案的資料尋找結構；半監督式結合少量有標籤與大量無標籤資料；強化學習則讓代理人依環境回饋改善長期策略。分類輸出類別，迴歸預測數值，分群找相似結構。再從資料特性挑選方法：決策樹以條件切分，SVM重視分類邊界與間隔，K-means以距離分群；CNN擅長局部空間特徵，RNN處理序列狀態，Transformer以注意力建立上下文關係。架構名稱不等於效果保證，仍要比較資料品質、資源、泛化與實際需求。',essentials:['有無目標標籤與回饋形式，是區分學習方式的重要線索。','分類、迴歸、分群是任務；CNN、樹等是方法，兩個分類軸不要混淆。','半監督式仍需可靠標籤與驗證，不能把自動猜測當成真實答案。','強化學習關注策略與累積回報，獎勵設計需對齊真正目標。','K-means受尺度、群數、初始化與離群值影響。','多模態需對齊來源與時序；更多模態不保證更好。'],contrasts:[{a:'分類',b:'分群',difference:'分類學習事先定義的標籤；分群由資料相似性形成群組，群號不自帶業務意義。'},{a:'訓練',b:'推論',difference:'訓練調整模型參數；推論使用既有參數處理新輸入，兩者資源需求可不同。'},{a:'RNN',b:'Transformer',difference:'RNN依序更新狀態；Transformer以注意力聯繫位置，原始架構不靠循環逐步處理。'}],checklist:['能由業務描述辨認目標是類別、數值或群組。','能解釋半監督式與強化學習的回饋差異。','能為CNN、RNN、Transformer各舉一例並指出限制。','不把模型名稱、參數量或分群結果當成效果保證。'],referenceIds:['google-ml','google-glossary','google-trees','google-kmeans','transformer-paper']},
 {code:'L11302',title:'機器學習模型評估與深度學習辨析',moduleId:'machine-learning',lessonIds:['ml-evaluation','ml-learning'],summary:'模型評估必須先定義正類，再區分TP、FP、FN、TN。Accuracy觀察全部預測有多少正確；Precision以預測正類為分母，回答警報有多可信；Recall以實際正類為分母，回答抓回多少目標；F1是Precision與Recall的調和平均，會懲罰只顧其中一邊的情形。類別不平衡時，高Accuracy仍可能完全漏掉少數正類。依情境衡量漏報與誤報成本，再以驗證集選門檻並保留獨立測試集。訓練成績明顯高於驗證可能是過度擬合，也應檢查切分與分布差異。多類別平均方式、分群切片與新環境測試都影響結論，不能用單一分數宣稱全面可靠。',essentials:['先指定正類；FP是誤報，FN是漏報。','Accuracy=(TP+TN)/(TP+TN+FP+FN)。','Precision=TP/(TP+FP)；Recall=TP/(TP+FN)。','F1=2PR/(P+R)=2TP/(2TP+FP+FN)，不是算術平均。','固定分數下降門檻，預測正類增加，Recall通常不減，但Precision不保證單調。','切分依時間、個體與來源設計；避免同一人的資料跨集合。'],contrasts:[{a:'Precision',b:'Recall',difference:'前者從模型發出的警報看真假；後者從真實正類看有無抓到，分母方向不同。'},{a:'過度擬合',b:'欠擬合',difference:'前者常訓練好、驗證差；後者連訓練規律也未充分學到，需查容量、特徵與優化。'},{a:'Macro平均',b:'Micro平均',difference:'Macro先算每類再等權平均；Micro先合併各類計數，容易反映多數類別的影響。'}],checklist:['能從情境重建四格混淆矩陣。','能手算四項指標並驗證分母。','能以錯誤成本解釋為何重視召回率或精確率。','能說明獨立測試、分群評估與門檻選擇的用途。'],referenceIds:['google-metrics','google-overfit','google-glossary']},
 {code:'L11401',title:'鑑別式與生成式AI基本原理',moduleId:'generative-ai',lessonIds:['genai-principles','genai-reliability'],summary:'鑑別式與生成式的區分，要回到模型的任務與學習目標。判斷照片類別、估計數值或標記風險常屬鑑別任務；產生新的文字、影像、音訊或其他內容則屬生成任務。生成並不代表內容真實，也不表示所有輸出都是完全未曾出現的創作。常見生成方法包括GAN的生成器與鑑別器對抗、VAE的機率式潛在表示與重建，以及擴散模型學習反向去噪。LLM依上下文處理token與產生文字，token不等於固定一個中文字；Transformer是架構，不限定只能做生成。幻覺、資料記憶與偏誤都需驗證，應以來源、用途、限制與品質測試共同判斷是否可採用。',essentials:['先看輸入輸出及訓練目標，不以產品名稱判定類型。','GAN的鑑別器提供真偽辨識訊號，生成器學習產生更像資料的樣本。','VAE學習機率式潛在表示，兼顧重建與分布約束。','擴散訓練涉及加噪與學習去噪；生成沿反向過程取得樣本。','Token切分依分詞器；字數相同不保證token數相同。','生成結果須檢查事實、引用、偏誤與資料權利。'],contrasts:[{a:'生成器',b:'鑑別器',difference:'在GAN中，生成器產生樣本，鑑別器判別真實或生成樣本；兩者角色互補而不同。'},{a:'VAE',b:'一般自編碼器',difference:'VAE包含機率式潛在變數與分布約束，不能只當成把原資料壓小再解壓。'},{a:'流暢度',b:'事實正確性',difference:'句子通順是語言品質；主張是否有證據支持是事實品質，需要分開評估。'}],checklist:['能分辨同一流程中的判斷與生成環節。','能比較GAN、VAE與擴散的基本機制。','不以語氣、引用格式或token數推定真實性。','知道模型架構不等於單一任務或單一產品。'],referenceIds:['google-ml','google-glossary','gan-paper','vae-paper','diffusion-paper','transformer-paper','ms-rag']},
 {code:'L11402',title:'鑑別式與生成式AI整合應用',moduleId:'generative-ai',lessonIds:['genai-principles','genai-reliability'],summary:'整合應用應拆成可檢查的輸入、處理與輸出階段，例如視覺辨識讀取現場狀態、ASR將語音轉為文字、分類器判別意圖、檢索取得授權資料、LLM整理回覆，最後以TTS合成語音。各階段可能使用不同模型，也可能由多模態模型共同處理，不能僅靠最後一句回答流暢就判定成功。評估時一方面測量各環節品質，一方面檢查端到端任務完成率、延遲、成本及人工接手效果。前一階段錯誤可能被後續放大，應保留來源、時間與可信度，針對低信心與高風險事件設計補問、拒答、重試或人工覆核。權限必須在檢索和工具執行時落實，不能只靠提示要求保密。',essentials:['CV、ASR、LLM、TTS分別處理視覺、語音辨識、語言與語音合成等能力。','先定義端到端成功，再選各環節可觀測的局部指標。','局部高分不保證整體高分，錯誤會串連並受到相依關係影響。','檢索需核對相關性、版本及存取權限；生成需核對證據支持度。','超時、低信心與工具失敗需要明確降級或人工接手機制。','多模態資料應核對時間、身分與對應事件，避免串錯訊息。'],contrasts:[{a:'ASR',b:'TTS',difference:'ASR把聲音辨識為文字；TTS依文字合成語音，方向相反。'},{a:'環節評估',b:'端到端評估',difference:'前者定位哪一階段出錯；後者衡量完整任務是否成功，應同時保留。'},{a:'有引用',b:'有依據',difference:'引用可存在卻不支持主張；必須逐項核對來源內容、有效版本及限制條件。'}],checklist:['能畫出至少四階段客服或巡檢流程。','能替每階段指定一項品質指標與失敗處理。','能解釋為何人工接手、權限檢查與日誌不可省略。','能判斷錯誤源自辨識、檢索、生成或播報。'],referenceIds:['ms-rag','google-ml','google-metrics','transformer-paper']},
 {code:'L12101',title:'No Code與Low Code基本概念',moduleId:'ai-tools',lessonIds:['low-code'],summary:'No Code主要透過視覺化元件、表單、範本與設定建立應用，Low Code則在可視化基礎上加入公式、程式或自訂整合。兩者界線依平台與情境不同，不能只靠有沒有拖拉畫面區分。優點常見於快速試作、流程共識與重複性工作自動化，但仍需理解資料結構、條件、觸發器、權限與例外處理。選擇平台時，應實測整合、效能、可攜性與營運需求，估算授權、用量、維護與移轉成本。低程式門檻不代表低風險；應建立測試與正式環境、變更紀錄、資料存取政策、負責人與還原流程。AI可以協助產生公式或流程，但產出仍需驗收，不能把生成成功當成部署後一定可靠。',essentials:['No Code與Low Code是開發方式，與是否使用AI是不同維度。','Low Code仍可能需要公式、條件、資料型態及API知識。','自動化流程包含觸發、條件、動作、連線、錯誤處理與權限。','平台內建連接器不代表使用者取得所有資料權限。','採用前評估資料可匯出性、供應商依賴、用量與維護成本。','以版本、測試環境、責任人、監控與還原管理應用生命週期。'],contrasts:[{a:'No Code',b:'Low Code',difference:'No Code主要靠設定完成；Low Code允許較多公式或程式擴充，但平台邊界不是固定二分。'},{a:'連接器',b:'連線與授權',difference:'連接器描述可用操作；連線保存特定身分的認證，實際可讀寫範圍仍需獨立控管。'},{a:'原型速度',b:'長期總成本',difference:'前者衡量試作快慢；後者還含用量、授權、維護、整合、治理與移轉。'}],checklist:['能依需求說明採No Code、Low Code或傳統開發的理由。','能列出流程中的觸發、條件與例外處理。','能辨認資料外流、過度授權與平台依賴風險。','能說明上線前測試及上線後維護分工。'],referenceIds:['ms-powerfx','ms-dlp','ms-alm']}
];

